<script lang="ts">
	import Search from '@lucide/svelte/icons/search';
	import Copy from '@lucide/svelte/icons/copy';
	import Check from '@lucide/svelte/icons/check';
	import ArrowUpRight from '@lucide/svelte/icons/arrow-up-right';
	import ProviderMark from './provider-mark.svelte';
	import EmptyState from './empty-state.svelte';
	import { formatCount, formatDate, providerName, privateLabel, type Status, type Call, type Model, type Account } from '$lib/management';
	let { screen, summary, calls, models, accounts, busy, toggleModel, navigate, showEmails = false }: { screen: string; summary: Status | null; calls: Call[]; models: Model[]; accounts: Account[]; busy: string; toggleModel: (model: Model) => void; navigate: (screen: string) => void; showEmails?: boolean } = $props();
	let search = $state('');
	let onlyErrors = $state(false);
	let copied = $state(false);
	let copyFailure = $state('');
	let tool = $state('openai');
	let filteredModels = $derived(models.filter(m => `${m.id} ${m.name} ${m.provider}`.toLowerCase().includes(search.toLowerCase())));
	let filteredCalls = $derived(calls.filter(c => (!onlyErrors || c.status >= 400 || c.error) && `${c.model} ${c.provider} ${c.account_id}`.toLowerCase().includes(search.toLowerCase())));
	let successRate = $derived(summary?.requests ? Math.round((summary.requests-summary.errors)/summary.requests*100) : null);
	let baseUrl = $derived(summary?.client_api_base_url ?? (typeof window === 'undefined' ? '' : `${window.location.origin}/v1`));
	let claudeConfig = $derived(`$env:ANTHROPIC_BASE_URL = '${baseUrl.replace(/\/v1$/, '').replace(/'/g, "''")}'\n$env:ANTHROPIC_AUTH_TOKEN = 'douane'\nclaude`);
	async function copy(value: string) { try { await navigator.clipboard.writeText(value); copied = true; copyFailure = ''; } catch { copied = false; copyFailure = 'Copie indisponible. Sélectionnez le texte pour le copier.'; } }
</script>

{#if screen === 'overview'}
	<div class="page-heading"><div><h1>Vue d'ensemble</h1><p class="page-description">L'activité de vos abonnements</p></div><span class="state-badge" class:inactive={!summary}><span class="status-pip"></span>{summary ? 'Service connecté' : 'Connexion indisponible'}</span></div>
	<div class="overview-stats"><div><p>Comptes actifs</p><strong>{summary ? summary.enabled_accounts : '-'}</strong><span>sur {summary?.accounts ?? 0} comptes</span></div><div><p>Requêtes</p><strong>{formatCount(summary?.requests)}</strong><span>{summary?.in_flight ?? 0} en cours</span></div><div><p>Tokens échangés</p><strong>{summary ? formatCount(summary.input_tokens+summary.output_tokens) : '-'}</strong><span>entrée et sortie</span></div><div><p>Cache relu</p><strong>{summary ? formatCount(summary.cache_read_tokens ?? 0) : '-'}</strong><span>tokens réutilisés</span></div><div><p>Requêtes réussies</p><strong>{successRate == null ? '-' : `${successRate} %`}</strong><span>{summary?.errors ?? 0} erreurs</span></div></div>
	<div class="section-toolbar"><div><h2>Activité récente</h2><p>Les dernières requêtes traitées par douane</p></div><button class="button subtle" onclick={() => navigate('activity')}>Tout voir<ArrowUpRight size={14}/></button></div>
	<section class="ledger">{#if !calls.length}<EmptyState title="Votre activité apparaîtra ici" description="Connectez un compte puis envoyez une première requête depuis votre outil." action="Ouvrir le démarrage rapide" onclick={() => navigate('quickstart')}/>{:else}<div class="table-scroll"><table><thead><tr><th>Modèle</th><th>Fournisseur</th><th>Heure</th><th>Statut</th><th>Durée</th></tr></thead><tbody>{#each calls.slice(0,8) as call (call.id)}<tr><td>{call.model}</td><td class="muted">{providerName(call.provider)}</td><td class="muted small">{formatDate(call.started_at)}</td><td><span class="http-status" class:error={call.status >= 400 || !!call.error}>{call.error ? 'Erreur' : call.status}</span></td><td class="tabular muted">{call.latency_ms == null ? '-' : `${call.latency_ms} ms`}</td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'models'}
	<div class="page-heading"><div><h1>Modèles</h1><p class="page-description">Les modèles disponibles avec vos comptes</p></div><span class="muted small">{models.length} modèles</span></div>
	<div class="section-toolbar"><p>Adresse compatible OpenAI <span class="inline-code">/v1/models</span></p><label class="search-input"><Search size={15}/><input type="search" bind:value={search} aria-label="Rechercher un modèle" placeholder="Rechercher un modèle"/></label></div>
	<section class="ledger">{#if !models.length}<EmptyState title="Aucun modèle disponible" description="Ajoutez un compte pour charger les modèles de son abonnement." action="Ajouter un compte" onclick={() => navigate('accounts')}/>{:else if !filteredModels.length}<EmptyState title="Aucun modèle correspondant" description="Essayez un autre nom de modèle ou de fournisseur."/>{:else}<div class="table-scroll"><table><thead><tr><th>Modèle</th><th>Identifiant</th><th>Fournisseur</th><th>Contexte</th><th>Disponible</th></tr></thead><tbody>{#each filteredModels as model (`${model.provider}:${model.id}`)}<tr><td>{model.name ?? model.id}</td><td class="account-filename">{model.id}</td><td><span class="inline-provider"><ProviderMark provider={model.provider} size={17}/>{providerName(model.provider)}</span></td><td class="tabular muted">{formatCount(model.context_length ?? undefined)}</td><td><button class="switch" class:on={model.enabled !== false} role="switch" aria-checked={model.enabled !== false} aria-label="Activer {model.name ?? model.id}" disabled={!!busy} onclick={() => toggleModel(model)}><span></span></button></td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'activity'}
	<div class="page-heading"><div><h1>Journal des requêtes</h1><p class="page-description">Chaque appel, son compte et sa consommation</p></div><span class="muted small">{calls.length} dernières requêtes</span></div>
	<div class="section-toolbar"><label class="check-label"><input type="checkbox" bind:checked={onlyErrors}/>Afficher les erreurs seulement</label><label class="search-input"><Search size={15}/><input type="search" bind:value={search} aria-label="Rechercher une requête" placeholder="Modèle, compte ou fournisseur"/></label></div>
	<section class="ledger">{#if !filteredCalls.length}<EmptyState title={calls.length ? 'Aucune requête correspondante' : 'Aucune requête pour le moment'} description={calls.length ? 'Modifiez votre recherche ou le filtre des erreurs.' : 'Les appels de vos outils apparaîtront ici avec leur résultat réel.'}/>{:else}<div class="table-scroll"><table><thead><tr><th>Heure</th><th>Modèle et compte</th><th>Fournisseur</th><th>Statut</th><th>Durée</th><th>Tokens</th></tr></thead><tbody>{#each filteredCalls as call (call.id)}<tr><td class="muted small">{formatDate(call.started_at)}</td><td>{call.model}<div class="account-filename">{privateLabel(accounts.find(a => a.id === call.account_id)?.name ?? call.account_id ?? 'Compte non communiqué',showEmails)}</div>{#if call.error}<p class="inline-error">{call.error}</p>{/if}</td><td class="muted">{providerName(call.provider)}</td><td><span class="http-status" class:error={call.status >= 400 || !!call.error}>{call.error ? 'Erreur' : call.status}</span></td><td class="tabular muted">{call.latency_ms == null ? '-' : `${call.latency_ms} ms`}</td><td class="tabular muted">{formatCount((call.input_tokens ?? 0)+(call.output_tokens ?? 0))}</td></tr>{/each}</tbody></table></div>{/if}</section>
{:else if screen === 'quickstart'}
	<div class="page-heading"><h1>Configurer un outil</h1></div>
	<div class="tool-tabs" aria-label="Choisir un outil"><button class="button" class:primary={tool === 'openai'} aria-pressed={tool === 'openai'} onclick={() => { tool = 'openai'; copied = false; copyFailure = ''; }}>Compatible OpenAI</button><button class="button" class:primary={tool === 'claude'} aria-pressed={tool === 'claude'} onclick={() => { tool = 'claude'; copied = false; copyFailure = ''; }}>Claude Code</button></div>
	<div class="setup-guide">
		{#if !accounts.length}<section><div><h2>Connecter un compte</h2><button class="button" onclick={() => navigate('accounts')}>Ouvrir les comptes<ArrowUpRight size={18}/></button></div></section>{/if}
		{#if tool === 'openai'}<section><div><h2>Adresse de base</h2><div class="copy-field"><code>{baseUrl}</code><button class="icon-button" onclick={() => copy(baseUrl)} aria-label="Copier l'adresse">{#if copied}<Check size={20}/>{:else}<Copy size={20}/>{/if}</button></div><p>Choisissez le mode compatible OpenAI de votre outil. S’il demande une clé, saisissez <code class="inline-code">douane</code>.</p><button class="button" onclick={() => navigate('models')}>Choisir un modèle<ArrowUpRight size={18}/></button></div></section>
		{:else}<section><div><h2>Claude Code</h2><p>Exécutez ces commandes dans PowerShell.</p><div class="copy-field config-code"><pre><code>{claudeConfig}</code></pre><button class="icon-button" onclick={() => copy(claudeConfig)} aria-label="Copier la configuration Claude Code">{#if copied}<Check size={20}/>{:else}<Copy size={20}/>{/if}</button></div><p>Claude Code utilisera le compte Claude connecté pour envoyer ses requêtes.</p>{#if !accounts.some(account => account.provider === 'claude' && account.enabled)}<button class="button" onclick={() => navigate('accounts')}>Connecter un compte Claude<ArrowUpRight size={18}/></button>{/if}</div></section>{/if}
		{#if copyFailure}<p class="inline-error" role="alert">{copyFailure}</p>{/if}
	</div>
{/if}

<style>
	.overview-stats { display: grid; grid-template-columns: repeat(5,1fr); border: 1px solid var(--border); border-radius: 14px; background: var(--surface); margin: 28px 0 34px; }.overview-stats>div { padding: 24px 20px; border-right: 1px solid var(--border); }.overview-stats>div:last-child { border: 0; }.overview-stats p { font-size: 15px; color: var(--muted); margin: 0 0 15px; }.overview-stats strong { display: block; font-family: var(--font-display); font-size: 34px; font-weight: 600; letter-spacing: -.045em; font-variant-numeric: tabular-nums; }.overview-stats span { font-size: 15px; color: var(--faint); display: block; margin-top: 12px; }
	.inline-provider { display: inline-flex; gap: 8px; align-items: center; }.http-status { font-size: 15px; color: var(--green); background: #4dd4ac09; border: 1px solid #4dd4ac20; padding: 4px 7px; border-radius: 6px; }.http-status.error { color: var(--red); background: #ff819509; border-color: #ff819530; }.account-filename { font-family: var(--account-font); font-size: 15px; color: var(--muted); margin-top: 5px; }.inline-error { max-width: 400px; font-size: 15px; color: var(--red); }.check-label { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; color: var(--muted); }.check-label input { accent-color: var(--primary); }.table-scroll { overflow-x: auto; }
	.setup-guide { max-width: 760px; margin-top: 30px; }.setup-guide section { display: flex; gap: 22px; border-bottom: 1px solid var(--border); padding: 28px 0; }.setup-guide section:first-child { padding-top: 0; }.setup-guide h2 { font-size: 16px; margin: 5px 0 12px; }.setup-guide p { color: var(--muted); font-size: 15px; line-height: 1.7; max-width: 600px; }.copy-field { display: flex; align-items: center; justify-content: space-between; border: 1px solid var(--border); background: var(--surface); border-radius: 10px; padding: 9px 13px; margin: 18px 0; }
	.tool-tabs { display: flex; flex-wrap: wrap; gap: 12px; }.setup-guide section>div { width: 100%; min-width: 0; }.setup-guide h2 { font-size: 20px; }.copy-field code { font-size: 16px; overflow-wrap: anywhere; }.config-code { align-items: flex-start; gap: 12px; }.config-code pre { min-width: 0; margin: 7px 0; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.8; }
	@media(max-width:700px) { .overview-stats { grid-template-columns: repeat(2,1fr); }.overview-stats>div { padding: 18px; border-bottom: 1px solid var(--border); }.overview-stats strong { font-size: 26px; } }
</style>
